import sys

n = int(sys.stdin.read().split()[0])
if n % 3:
    print('Error')
else:
    total = 0
    for months, price in ((12, 15000), (9, 12000), (6, 9000), (3, 5000)):
        while n >= months:
            n -= months
            total += price
    print(total)

